<?php require_once '../includes/auth.php';require_supervision();verify_csrf();$id=(int)($_POST['id']??0);$d=$_POST['decision']??'';$note=trim($_POST['note']??'');if(!in_array($d,['verified','rejected'],true))exit('Invalid decision');$s=mysqli_prepare($conn,"UPDATE operational_reports SET verification_status=?,verification_note=?,verified_by=? WHERE id=?");$uid=user()['id'];mysqli_stmt_bind_param($s,'ssii',$d,$note,$uid,$id);mysqli_stmt_execute($s);log_activity('status_changed','reports','Report '.$d,$id);flash('success','Report '.$d.'.');redirect('list.php');
